-- ВАЖНО: файл для ПЕРВОНАЧАЛЬНОЙ загрузки демо-каталога. Он сначала удаляет все DEMO-* и создаёт их заново
-- (id товаров меняются, слетают характеристики). Демо-данные теперь постоянные — повторно НЕ запускать.
-- Любые дальнейшие изменения делаются отдельными безопасными миграциями (например product_attributes.sql).
-- ДЕМО-товары для новых плиток каталога (чтобы в каждой категории что-то было видно).
-- Все артикулы начинаются с DEMO- — когда появятся реальные товары, удалить одной строкой:
--   delete from products where sku like 'DEMO-%';
-- Запустить в Supabase → SQL Editor. Товары попадут в магазин владельца.
delete from products where sku like 'DEMO-%';

with s as (select store_id from profiles where role = 'owner' limit 1)
insert into products (store_id, sku, name, brand, category, price, description, characteristics, purpose, in_stock, image_url)
select s.store_id, v.sku, v.name, v.brand, v.category, v.price, v.description, v.characteristics, v.purpose, true, '/demo/' || lower(v.sku) || '.svg?v=2'
from s, (values
